/**
 * Root Router — composes all domain-specific routers into the app router.
 * 
 * This file uses router groups to organize 107+ routers into 7 logical groups,
 * then flattens them using mergeRouters to maintain API compatibility.
 * 
 * Client code continues to work unchanged: trpc.auth.me.useQuery()
 * (NOT trpc.core.auth.me.useQuery())
 */
import { mergeRouters } from "./_core/trpc";

// Router groups
import { coreRouter } from "./router-groups/core";
import { governanceGroupRouter } from "./router-groups/governance";
import { operationsRouter } from "./router-groups/operations";
import { intelligenceRouter } from "./router-groups/intelligence";
import { marketplaceGroupRouter } from "./router-groups/marketplace";
import { experienceRouter } from "./router-groups/experience";
import { extensibilityRouter } from "./router-groups/extensibility";

export const appRouter = mergeRouters(
  coreRouter,
  governanceGroupRouter,
  operationsRouter,
  intelligenceRouter,
  marketplaceGroupRouter,
  experienceRouter,
  extensibilityRouter
);

export type AppRouter = typeof appRouter;

