/**
 * Supabase Adapter for Gravito
 * 
 * This adapter wraps supabase-db.ts functions to provide camelCase property names
 * that are compatible with the existing routers.ts code.
 */

import * as supabaseDb from './supabase-db';
import { generalLog } from './_core/logger';

// ============ Type Converters ============

function snakeToCamel(str: string): string {
  return str.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
}

function convertKeysToCamel<T extends Record<string, unknown>>(obj: T): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      result[snakeToCamel(key)] = obj[key];
    }
  }
  return result;
}

// ============ User Types (camelCase) ============

export interface User {
  id: number;
  openId: string;
  name: string | null;
  email: string | null;
  loginMethod: string | null;
  passwordHash: string | null;
  role: 'admin' | 'user';
  lastSignedIn: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface ApiKey {
  id: number;
  userId: number;
  keyHash: string;
  keyPrefix: string;
  name: string;
  isActive: boolean;
  lastUsedAt: string | null;
  createdAt: string;
}

export interface Subscription {
  id: number;
  userId: number;
  plan: string;
  stripeCustomerId: string | null;
  stripeSubscriptionId: string | null;
  status: string;
  currentPeriodStart: string | null;
  currentPeriodEnd: string | null;
  cancelAtPeriodEnd: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface ApiUsage {
  id: number;
  userId: number;
  apiKeyId: number | null;
  endpoint: string;
  callCount: number;
  date: string;
  createdAt: string;
}

export interface EmotionalHistory {
  id: number;
  userId: number;
  externalUserId: string | null;
  emotion: string;
  valence: number;
  arousal: number;
  escalationRisk: 'low' | 'medium' | 'high';
  context: string | null;
  conversationId: string | null;
  createdAt: string;
}

export interface EmotionalPattern {
  id: number;
  userId: number;
  externalUserId: string | null;
  patternType: 'recurring_frustration' | 'escalation_prone' | 'positive_engagement' | 'time_sensitive' | 'topic_triggered';
  description: string;
  triggers: string | null;
  frequency: number;
  lastOccurrence: string;
  recommendedApproach: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface BillingHistory {
  id: number;
  userId: number;
  stripeInvoiceId: string | null;
  stripePaymentIntentId: string | null;
  amount: number;
  currency: string;
  status: string;
  description: string | null;
  createdAt: string;
}

// ============ User Functions ============

export async function upsertUser(userData: {
  openId: string;
  name?: string | null;
  email?: string | null;
  loginMethod?: string | null;
  passwordHash?: string | null;
  role?: 'admin' | 'user';
  lastSignedIn?: Date;
}): Promise<void> {
  await supabaseDb.upsertUser(userData);
}

export async function getUserByOpenId(openId: string): Promise<User | null> {
  const user = await supabaseDb.getUserByOpenId(openId);
  if (!user) return null;
  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
}

export async function getUserById(id: number): Promise<User | null> {
  const user = await supabaseDb.getUserById(id);
  if (!user) return null;
  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
}

export async function getUserByEmail(email: string): Promise<User | null> {
  const user = await supabaseDb.getUserByEmail(email);
  if (!user) return null;
  return convertKeysToCamel(user as unknown as Record<string, unknown>) as unknown as User;
}

// ============ API Key Functions ============

export async function createApiKey(userId: number, name?: string): Promise<{ key: string; prefix: string }> {
  const result = await supabaseDb.createApiKey(userId, name);
  if (!result) {
    throw new Error('Failed to create API key');
  }
  return result;
}

export async function getApiKeysByUserId(userId: number): Promise<Partial<ApiKey>[]> {
  const keys = await supabaseDb.getApiKeysByUserId(userId);
  return keys.map(k => convertKeysToCamel(k as unknown as Record<string, unknown>)) as Partial<ApiKey>[];
}

export async function validateApiKey(key: string): Promise<ApiKey | null> {
  const apiKey = await supabaseDb.validateApiKey(key);
  if (!apiKey) return null;
  return convertKeysToCamel(apiKey as unknown as Record<string, unknown>) as unknown as ApiKey;
}

export async function deleteApiKey(userId: number, keyId: number): Promise<boolean> {
  return supabaseDb.deleteApiKey(userId, keyId);
}

export async function regenerateApiKey(userId: number, keyId: number): Promise<{ key: string; prefix: string } | null> {
  return supabaseDb.regenerateApiKey(userId, keyId);
}

// ============ Subscription Functions ============

export async function getSubscriptionByUserId(userId: number): Promise<Subscription | null> {
  const sub = await supabaseDb.getSubscriptionByUserId(userId);
  if (!sub) return null;
  return convertKeysToCamel(sub as unknown as Record<string, unknown>) as unknown as Subscription;
}

export async function createOrUpdateSubscription(subData: {
  userId: number;
  plan: string;
  stripeCustomerId?: string | null;
  stripeSubscriptionId?: string | null;
  status?: string;
  currentPeriodStart?: Date | null;
  currentPeriodEnd?: Date | null;
  cancelAtPeriodEnd?: boolean;
}): Promise<boolean> {
  return supabaseDb.createOrUpdateSubscription(subData);
}

// ============ Usage Functions ============

export async function recordApiUsage(userId: number, apiKeyId: number | null, endpoint: string): Promise<void> {
  return supabaseDb.recordApiUsage(userId, apiKeyId, endpoint);
}

export async function getUsageByUserId(userId: number, days: number = 30): Promise<ApiUsage[]> {
  const usage = await supabaseDb.getUsageByUserId(userId, days);
  return usage.map(u => convertKeysToCamel(u as unknown as Record<string, unknown>) as unknown as ApiUsage);
}

export async function getTotalUsageThisMonth(userId: number): Promise<number> {
  return supabaseDb.getTotalUsageThisMonth(userId);
}

export async function getUsageBreakdownByEndpoint(userId: number, days: number = 30) {
  const dbModule = await import('./db');
  return dbModule.getUsageBreakdownByEndpoint(userId, days);
}

// ============ Billing Functions ============

export async function getBillingHistory(userId: number): Promise<BillingHistory[]> {
  const history = await supabaseDb.getBillingHistory(userId);
  return history.map(h => convertKeysToCamel(h as unknown as Record<string, unknown>) as unknown as BillingHistory);
}

export async function recordBillingEvent(billingData: {
  userId: number;
  stripeInvoiceId?: string | null;
  stripePaymentIntentId?: string | null;
  amount: number;
  currency?: string;
  status: string;
  description?: string | null;
}): Promise<boolean> {
  return supabaseDb.addBillingRecord(billingData);
}

// ============ Rate Limiting ============

export async function checkRateLimit(
  userId: number,
  plan: string
): Promise<{ allowed: boolean; remaining: number; resetAt: Date }> {
  return supabaseDb.checkRateLimit(userId, plan);
}

// ============ Plan Limits (static, no DB needed) ============

const PLAN_LIMITS: Record<string, { calls: number; rate: number }> = {
  free: { calls: 100, rate: 10 },
  builder: { calls: 5000, rate: 50 },
  startup: { calls: 25000, rate: 100 },
  scale: { calls: 100000, rate: 250 },
  business: { calls: 500000, rate: 500 },
  enterprise: { calls: 2000000, rate: 1000 },
  enterprise_plus: { calls: 10000000, rate: 2500 },
};

export function getPlanLimit(plan: string): { calls: number; rate: number } {
  return PLAN_LIMITS[plan] || PLAN_LIMITS.free;
}

// ============ Test Connection ============

export async function testConnection(): Promise<boolean> {
  return supabaseDb.testSupabaseConnection();
}


// ============ Lead Types (camelCase) ============

export interface Lead {
  id: number;
  email: string;
  company: string | null;
  companySize: string | null;
  industry: string | null;
  sourcePage: string | null;
  utmSource: string | null;
  utmMedium: string | null;
  utmCampaign: string | null;
  utmContent: string | null;
  utmTerm: string | null;
  escalationRisk: number | null;
  churnProbability: number | null;
  valueAtRisk: number | null;
  scanConversation: string | null;
  leadScore: number;
  leadTier: 'cold' | 'warm' | 'hot' | 'qualified';
  status: string;
  notes: string | null;
  ownerNotified: boolean;
  crisisReportSent: boolean;
  pilotAgentTriggered: boolean;
  lastContactedAt: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface LeadActivity {
  id: number;
  leadId: number;
  activityType: string;
  metadata: Record<string, unknown> | null;
  createdAt: string;
}

// ============ Lead Functions ============

function convertLeadToCamel(lead: supabaseDb.Lead): Lead {
  return {
    id: lead.id,
    email: lead.email,
    company: lead.company_name,
    companySize: lead.company_size,
    industry: lead.industry,
    sourcePage: lead.source_page,
    utmSource: lead.utm_source,
    utmMedium: lead.utm_medium,
    utmCampaign: lead.utm_campaign,
    utmContent: null, // Not in Supabase schema
    utmTerm: null, // Not in Supabase schema
    escalationRisk: lead.escalation_risk,
    churnProbability: lead.churn_probability,
    valueAtRisk: lead.value_at_risk,
    scanConversation: null, // Not in Supabase schema yet
    leadScore: lead.lead_score,
    leadTier: lead.lead_tier,
    status: lead.status,
    notes: lead.notes,
    ownerNotified: false, // Not in Supabase schema yet
    crisisReportSent: false, // Not in Supabase schema yet
    pilotAgentTriggered: false, // Not in Supabase schema yet
    lastContactedAt: null, // Not in Supabase schema yet
    createdAt: lead.created_at,
    updatedAt: lead.updated_at,
  };
}

export async function createLead(leadData: {
  email: string;
  company?: string | null;
  sourcePage?: string | null;
  utmSource?: string | null;
  utmMedium?: string | null;
  utmCampaign?: string | null;
  utmContent?: string | null;
  utmTerm?: string | null;
  escalationRisk?: number | null;
  churnProbability?: number | null;
  valueAtRisk?: number | null;
  scanConversation?: string | null;
}): Promise<Lead | null> {
  const result = await supabaseDb.createLead({
    email: leadData.email,
    companyName: leadData.company,
    sourcePage: leadData.sourcePage,
    utmSource: leadData.utmSource,
    utmMedium: leadData.utmMedium,
    utmCampaign: leadData.utmCampaign,
    escalationRisk: leadData.escalationRisk,
    churnProbability: leadData.churnProbability,
    valueAtRisk: leadData.valueAtRisk,
  });

  if (!result) return null;
  return convertLeadToCamel(result);
}

export async function getLeadByEmail(email: string): Promise<Lead | null> {
  const lead = await supabaseDb.getLeadByEmail(email);
  if (!lead) return null;
  return convertLeadToCamel(lead);
}

export async function getLeadById(id: number): Promise<Lead | null> {
  const lead = await supabaseDb.getLeadById(id);
  if (!lead) return null;
  return convertLeadToCamel(lead);
}

export async function updateLead(id: number, updates: {
  status?: string;
  notes?: string;
  escalationRisk?: number | null;
  churnProbability?: number | null;
  valueAtRisk?: number | null;
  scanConversation?: string | null;
  lastContactedAt?: Date;
  ownerNotified?: boolean;
  crisisReportSent?: boolean;
  pilotAgentTriggered?: boolean;
}): Promise<boolean> {
  return supabaseDb.updateLead(id, updates);
}

export async function getAllLeads(limit: number = 50): Promise<Lead[]> {
  const leads = await supabaseDb.getAllLeads(limit);
  return leads.map(convertLeadToCamel);
}

export async function getLeadsByStatus(status: string, limit: number = 50): Promise<Lead[]> {
  const leads = await supabaseDb.getLeadsByStatus(status, limit);
  return leads.map(convertLeadToCamel);
}

export async function getLeadsByTier(tier: string, limit: number = 50): Promise<Lead[]> {
  const leads = await supabaseDb.getLeadsByTier(tier, limit);
  return leads.map(convertLeadToCamel);
}

export async function getHighValueLeads(minScore: number = 50, limit: number = 20): Promise<Lead[]> {
  const leads = await supabaseDb.getHighValueLeads(minScore, limit);
  return leads.map(convertLeadToCamel);
}

export async function getLeadStats(): Promise<{
  total: number;
  byStatus: Record<string, number>;
  byTier: Record<string, number>;
  avgScore: number;
  todayCount: number;
}> {
  return supabaseDb.getLeadStats();
}

// ============ Lead Activity Functions ============

function convertActivityToCamel(activity: supabaseDb.LeadActivity): LeadActivity {
  return {
    id: activity.id,
    leadId: activity.lead_id,
    activityType: activity.activity_type,
    metadata: activity.metadata,
    createdAt: activity.created_at,
  };
}

export async function logLeadActivity(
  leadId: number,
  activityType: string,
  metadata: Record<string, unknown> = {}
): Promise<boolean> {
  return supabaseDb.logLeadActivity(leadId, activityType, metadata);
}

export async function getLeadActivities(leadId: number, limit: number = 50): Promise<LeadActivity[]> {
  const activities = await supabaseDb.getLeadActivities(leadId, limit);
  return activities.map(convertActivityToCamel);
}


// ============ Additional Subscription Functions ============

export async function updateSubscriptionByStripeId(
  stripeSubscriptionId: string,
  updates: {
    plan?: string;
    status?: string;
    currentPeriodStart?: Date | null;
    currentPeriodEnd?: Date | null;
    cancelAtPeriodEnd?: boolean;
  }
): Promise<boolean> {
  return supabaseDb.updateSubscriptionByStripeId(stripeSubscriptionId, updates);
}


// ============ Emotional History Functions ============

export async function recordEmotionalHistory(data: {
  userId: number;
  externalUserId?: string | null;
  emotion: string;
  valence: number;
  arousal: number;
  escalationRisk?: 'low' | 'medium' | 'high';
  context?: string | null;
  conversationId?: string | null;
}): Promise<number | null> {
  return supabaseDb.recordEmotionalHistory(data);
}

export async function getEmotionalHistoryByUser(userId: number, externalUserId?: string, limit?: number): Promise<EmotionalHistory[]> {
  const history = await supabaseDb.getEmotionalHistoryByUser(userId, externalUserId, limit);
  return history.map(h => convertKeysToCamel(h as unknown as Record<string, unknown>) as unknown as EmotionalHistory);
}

// ============ Emotional Pattern Functions ============

export async function saveEmotionalPattern(data: {
  userId: number;
  externalUserId?: string | null;
  patternType: 'recurring_frustration' | 'escalation_prone' | 'positive_engagement' | 'time_sensitive' | 'topic_triggered';
  description: string;
  triggers?: string | null;
  frequency?: number;
  recommendedApproach?: string | null;
}): Promise<boolean> {
  return supabaseDb.saveEmotionalPattern(data);
}

export async function getEmotionalPatternsByUser(userId: number, externalUserId?: string): Promise<EmotionalPattern[]> {
  const patterns = await supabaseDb.getEmotionalPatternsByUser(userId, externalUserId);
  return patterns.map(p => convertKeysToCamel(p as unknown as Record<string, unknown>) as unknown as EmotionalPattern);
}

export async function findExistingPattern(userId: number, externalUserId: string, patternType: string): Promise<EmotionalPattern | null> {
  const pattern = await supabaseDb.findExistingPattern(userId, externalUserId, patternType);
  if (!pattern) return null;
  return convertKeysToCamel(pattern as unknown as Record<string, unknown>) as unknown as EmotionalPattern;
}

export async function updateEmotionalPattern(
  patternId: number,
  updates: {
    description?: string;
    triggers?: string | null;
    recommendedApproach?: string | null;
    frequency?: number;
  }
): Promise<boolean> {
  return supabaseDb.updateEmotionalPattern(patternId, updates);
}


// ============ Demo Request Functions ============

export interface DemoRequest {
  id: number;
  firstName: string;
  lastName: string;
  email: string;
  company: string;
  jobTitle: string | null;
  companySize: string | null;
  timeline: string | null;
  useCase: string | null;
  additionalNotes: string | null;
  status: string;
  ownerNotified: boolean;
  createdAt: string;
  updatedAt: string;
}

export async function createDemoRequest(data: {
  firstName: string;
  lastName: string;
  email: string;
  company: string;
  jobTitle?: string;
  companySize?: string;
  timeline?: string;
  useCase?: string;
  additionalNotes?: string;
}): Promise<DemoRequest> {
  // Use Supabase to insert the demo request
  const { supabase } = await import('./supabase');

  const { data: result, error } = await supabase
    .from('demo_requests')
    .insert({
      first_name: data.firstName,
      last_name: data.lastName,
      email: data.email,
      company: data.company,
      job_title: data.jobTitle || null,
      company_size: data.companySize || null,
      timeline: data.timeline || null,
      use_case: data.useCase || null,
      additional_notes: data.additionalNotes || null,
      status: 'new',
      owner_notified: false,
    })
    .select()
    .single();

  if (error) {
    generalLog.error('Failed to create demo request:', error);
    throw new Error('Failed to submit demo request');
  }

  return {
    id: result.id,
    firstName: result.first_name,
    lastName: result.last_name,
    email: result.email,
    company: result.company,
    jobTitle: result.job_title,
    companySize: result.company_size,
    timeline: result.timeline,
    useCase: result.use_case,
    additionalNotes: result.additional_notes,
    status: result.status,
    ownerNotified: result.owner_notified,
    createdAt: result.created_at,
    updatedAt: result.updated_at,
  };
}

export async function getDemoRequests(limit: number = 50): Promise<DemoRequest[]> {
  const { supabase } = await import('./supabase');

  const { data, error } = await supabase
    .from('demo_requests')
    .select('*')
    .order('created_at', { ascending: false })
    .limit(limit);

  if (error) {
    generalLog.error('Failed to get demo requests:', error);
    return [];
  }

  return data.map((r: any) => ({
    id: r.id,
    firstName: r.first_name,
    lastName: r.last_name,
    email: r.email,
    company: r.company,
    jobTitle: r.job_title,
    companySize: r.company_size,
    timeline: r.timeline,
    useCase: r.use_case,
    additionalNotes: r.additional_notes,
    status: r.status,
    ownerNotified: r.owner_notified,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  }));
}


// ============ Pilot Requests ============

export interface PilotRequest {
  id: number;
  name: string;
  email: string;
  company: string | null;
  role: string | null;
  systemUrl: string | null;
  description: string | null;
  source: 'website' | 'cli' | 'github' | 'referral' | 'other';
  status: 'new' | 'contacted' | 'scanning' | 'report_sent' | 'pilot_active' | 'converted' | 'declined';
  scanResult: unknown | null;
  reportUrl: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
  contactedAt: string | null;
}

export async function createPilotRequest(data: {
  name: string;
  email: string;
  company?: string;
  role?: string;
  systemUrl?: string;
  description?: string;
  source?: 'website' | 'cli' | 'github' | 'referral' | 'other';
}): Promise<{ id: number }> {
  const { supabase } = await import('./supabase');

  const { data: result, error } = await supabase
    .from('pilot_requests')
    .insert({
      name: data.name,
      email: data.email,
      company: data.company || null,
      role: data.role || null,
      system_url: data.systemUrl || null,
      description: data.description || null,
      source: data.source || 'website',
      status: 'new',
    })
    .select('id')
    .single();

  if (error) {
    generalLog.error('Failed to create pilot request:', error);
    throw new Error('Failed to submit pilot request');
  }

  return { id: result.id };
}

export async function getPilotRequestById(id: number): Promise<PilotRequest | null> {
  const { supabase } = await import('./supabase');

  const { data, error } = await supabase
    .from('pilot_requests')
    .select('*')
    .eq('id', id)
    .single();

  if (error) {
    generalLog.error('Failed to get pilot request by id:', error);
    return null;
  }

  return data as PilotRequest;
}

export async function getPilotRequests(limit: number = 50): Promise<PilotRequest[]> {
  const { supabase } = await import('./supabase');

  const { data, error } = await supabase
    .from('pilot_requests')
    .select('*')
    .order('createdAt', { ascending: false })
    .limit(limit);

  if (error) {
    generalLog.error('Failed to get pilot requests:', error);
    return [];
  }

  return data as PilotRequest[];
}

export async function updatePilotRequestStatus(
  id: number,
  status: 'new' | 'contacted' | 'scanning' | 'report_sent' | 'pilot_active' | 'converted' | 'declined',
  notes?: string
): Promise<void> {
  const { supabase } = await import('./supabase');

  const updates: Record<string, unknown> = { status };
  if (notes !== undefined) {
    updates.notes = notes;
  }
  if (status === 'contacted') {
    updates.contactedAt = new Date().toISOString();
  }

  const { error } = await supabase
    .from('pilot_requests')
    .update(updates)
    .eq('id', id);

  if (error) {
    generalLog.error('Failed to update pilot request:', error);
    throw new Error('Failed to update pilot request');
  }
}


// ============ Gravito Stats Functions ============

export async function getGravitoStats(userId: number, days: number = 30): Promise<{
  total: number;
  passed: number;
  blocked: number;
  warned: number;
  proofsGenerated: number;
  artifactsReviewed: number;
  gatesBlocked: number;
  lastRunAt: string | null;
  averageScore: number | null;
}> {
  // For now, return mock data until Gravito tables are added to Supabase
  // This allows the dashboard to render without errors
  return {
    total: 0,
    passed: 0,
    blocked: 0,
    warned: 0,
    proofsGenerated: 0,
    artifactsReviewed: 0,
    gatesBlocked: 0,
    lastRunAt: null,
    averageScore: null,
  };
}


// ============ MCP Per-Key Usage ============

export async function getUsageByApiKeyPrefix(keyPrefix: string, days: number = 30) {
  const dbModule = await import('./db');
  return dbModule.getUsageByApiKeyPrefix(keyPrefix, days);
}


// ============ API Key Rate Limit ============

export async function updateApiKeyRateLimit(userId: number, keyId: number, rateLimitOverride: number | null) {
  const dbModule = await import('./db');
  return dbModule.updateApiKeyRateLimit(userId, keyId, rateLimitOverride);
}

