/**
 * Subscription & Usage Router — handles subscription state and usage stats
 */
import { router } from "../_core/trpc";
import { governedProtectedProcedure } from "../governance/trpc-enforcement";
import { z } from "zod";
import * as db from "../supabase-adapter";

const protectedProcedure = governedProtectedProcedure;

export const subscriptionRouter = router({
  current: protectedProcedure.query(async ({ ctx }) => {
    const subscription = await db.getSubscriptionByUserId(ctx.user.id);
    if (!subscription) {
      await db.createOrUpdateSubscription({
        userId: ctx.user.id,
        plan: "free",
        status: "active",
      });
      return db.getSubscriptionByUserId(ctx.user.id);
    }
    return subscription;
  }),

  billingHistory: protectedProcedure.query(async ({ ctx }) => {
    return db.getBillingHistory(ctx.user.id);
  }),
});

export const usageRouter = router({
  stats: protectedProcedure
    .input(z.object({
      days: z.number().min(1).max(90).default(30),
    }).optional())
    .query(async ({ ctx, input }) => {
      const days = input?.days || 30;
      const usage = await db.getUsageByUserId(ctx.user.id, days);
      const total = await db.getTotalUsageThisMonth(ctx.user.id);
      const subscription = await db.getSubscriptionByUserId(ctx.user.id);
      const limit = db.getPlanLimit(subscription?.plan || "free");

      const gravitoStats = await db.getGravitoStats(ctx.user.id, days);

      return {
        daily: usage,
        total,
        limit: limit.calls,
        remaining: Math.max(0, limit.calls - total),
        percentage: Math.round((total / limit.calls) * 100),
        proofsGenerated: gravitoStats.proofsGenerated,
        artifactsReviewed: gravitoStats.artifactsReviewed,
        gatesBlocked: gravitoStats.gatesBlocked,
        lastRunAt: gravitoStats.lastRunAt,
        averageScore: gravitoStats.averageScore,
      };
    }),

  /**
   * Tool breakdown — groups API usage by endpoint for the current user.
   * Returns real data from the api_usage table.
   */
  toolBreakdown: protectedProcedure
    .input(z.object({
      days: z.number().min(1).max(90).default(30),
    }).optional())
    .query(async ({ ctx, input }) => {
      const days = input?.days || 30;
      return db.getUsageBreakdownByEndpoint(ctx.user.id, days);
    }),
});

